class NativeLcdText final {
 using T=LcdTextTask;using K=T::Kind;using S=T::Stage;
public:
 struct CodeRange{uint32_t begin,end;};inline static constexpr std::array<CodeRange,2>CodeRanges{{{0x22c0,0x22da},{0x2318,0x23b2}}};
 bool active()const{return depth_||lcd_.active();}void reset(){depth_=0;lcd_.reset();steps_=0;}uint64_t steps()const{return steps_;}
 static bool candidate(unsigned at){return (at>=0x22c0&&at<0x22da)||(at>=0x2318&&at<0x23b2);}
 bool step(Stage1Cpu&c){if(midi_projection::blocked(c))return false;auto at=unsigned(c.getPC());if(NativeFlashState::candidate(at)){if(!lcd_.step(c))return false;++steps_;return true;}
  if(!depth_||boundary(jobs_[depth_-1])!=at){K k;if(at==0x22c0)k=K::RawData;else if(at==0x2318)k=K::Data;else if(at==0x2370)k=K::DirectData;else if(at==0x232e)k=K::Initialize;else if(at==0x233c)k=K::Cursor;else if(at==0x2368)k=K::Cgram;else if(at==0x2342)k=K::Spaces;else if(at==0x234c)k=K::FirstLine;else if(at==0x235a)k=K::SecondLine;else if(at==0x237e)k=K::Character;else if(at==0x239e)k=K::String;else return false;if(depth_==jobs_.size())throw std::logic_error("Native K LCD text capacity");jobs_[depth_++]=T{k,uint8_t(c.reg8(14)),uint8_t(c.reg8(6)),uint32_t(c.reg32(6))};}
  auto&t=jobs_[depth_-1];if(t.awaiting())t.resumeChild(uint8_t(c.reg8(14)));if(at!=boundary(t))throw std::logic_error("Native K LCD text boundary");if(c.pending_irqs)c.read8(0xfffff2);auto len=bytes(t);auto cr=credits(t,c,len);auto cost=t.nextClocks(cr);auto begin=c.cycles;c.fetchClocks(len);c.pc=c.makepc(at+1);project(t,c);
  t.advanceBefore(cost,cr,[&](unsigned index){c.reg8(14)=c.read8(int(t.source()+index));++c.reg32(5);val(c,c.reg8(14));c.clockI(2);return uint8_t(c.reg8(14));},[&](T::Write field,unsigned value){auto r=field==T::Write::Port?8:14;val(c,c.reg8(r));c.write8(int8_t(value),field==T::Write::Port?0xffffd3:0xffffc7);});
  if(c.cycles-begin!=cost)throw std::logic_error("Native K LCD text clocks differ");if(t.complete())--depth_;else if(!t.awaiting())c.pc=c.makepc(boundary(t));++steps_;return true;
 }
private:
 static void val(Stage1Cpu&c,int value){midi_projection::val(c,value);}static void pop(Stage1Cpu&c,unsigned r,bool word){if(word)c.reg16(r)=int16_t(c.read16(int(c.getSP())));else c.reg32(r)=int32_t(c.read32(int(c.getSP())));c.setSP(c.getSP()+(word?2:4));val(c,word?c.reg16(r):c.reg32(r));c.clockI(2);}static void push(Stage1Cpu&c,unsigned r,bool word){c.setSP(c.getSP()-(word?2:4));if(word)c.write16(c.reg16(r),int(c.getSP()));else c.write32(c.reg32(r),int(c.getSP()));val(c,word?c.reg16(r):c.reg32(r));c.clockI(2);}
 static unsigned boundary(const T&t){auto k=t.kind();switch(t.stage()){
 case S::Retain:return k==K::String?0x239e:k==K::Data?0x2318:k==K::DirectData?0x2370:0x22c0;case S::Bind:return 0x23a2;case S::Read:return 0x23a4;case S::SelectEnd:return 0x23a6;case S::DispatchCharacter:return 0x23a8;case S::RepeatString:return 0x23aa;case S::Restore:return k==K::String?0x23ac:0x22d6;
 case S::Return:return k==K::RawData?0x22d8:k==K::Data?0x232c:k==K::DirectData?0x237c:k==K::Initialize?0x233a:k==K::Cursor?0x2340:k==K::Cgram?0x236e:k==K::Spaces?0x234a:k==K::FirstLine?0x2358:k==K::SecondLine?0x2366:k==K::String?0x23b0:t.path()==0?0x2386:t.path()==1?0x2390:0x239c;
 case S::PrepareFirst:return 0x22c2;case S::PublishFirst:return 0x22c4;case S::PrepareStrobe:return 0x22c6;case S::PublishStrobe:return 0x22c8;case S::PublishData:return 0x22ca;case S::Pause1:return 0x22cc;case S::Pause2:return 0x22ce;case S::Pause3:return 0x22d0;case S::PrepareRelease:return 0x22d2;case S::PublishRelease:return 0x22d4;
 case S::Ready:return k==K::Data?0x231a:0x2372;case S::CompareAddress:return 0x231c;case S::SelectAddress:return 0x231e;case S::PrepareWrap:return 0x2320;case S::Wrap:return 0x2322;case S::ReadyAgain:return 0x2326;case S::RestoreData:return k==K::Data?0x2328:0x2376;case S::DispatchData:return k==K::Data?0x232a:k==K::DirectData?0x2378:0x2382;
 case S::PrepareCommand1:return 0x232e;case S::Command1:return 0x2330;case S::PrepareCommand2:return 0x2332;case S::Command2:return 0x2334;case S::PrepareCommand3:return 0x2336;case S::Command3:return 0x2338;case S::CursorValue:return k==K::Cursor?0x233c:0x2368;case S::CursorCommand:return k==K::Cursor?0x233e:0x236a;
 case S::PrepareSpace:return 0x2342;case S::WriteSpace:return 0x2344;case S::DecrementSpaces:return 0x2346;case S::RepeatSpaces:return 0x2348;case S::PrepareLine:return k==K::FirstLine?0x234c:0x235a;case S::LineCursor:return k==K::FirstLine?0x234e:0x235c;case S::CountLine:return k==K::FirstLine?0x2350:0x235e;case S::LineSpaces:return k==K::FirstLine?0x2352:0x2360;case S::PrepareLineAgain:return k==K::FirstLine?0x2354:0x2362;case S::LineCursorAgain:return k==K::FirstLine?0x2356:0x2364;
 case S::TestSign:return 0x237e;case S::SelectSign:return 0x2380;case S::CompareClear:return 0x2388;case S::SelectClear:return 0x238a;case S::ClearSecond:return 0x238c;case S::ClearFirst:return 0x238e;case S::CompareControl:return 0x2392;case S::SelectControl:return 0x2394;case S::AdjustControl:return 0x2396;case S::ControlCommand:return 0x2398;case S::Complete:return 0;}return 0;}
 static unsigned bytes(const T&t){auto s=t.stage();return s==S::Retain&&t.kind()==K::String||s==S::Restore&&t.kind()==K::String||s==S::Ready&&t.kind()==K::DirectData||s==S::DispatchData&&t.kind()!=K::Data||s==S::Wrap||s==S::ControlCommand||s==S::CursorCommand&&t.kind()==K::Cgram?4:2;}
 static unsigned bus(unsigned at,unsigned n,int last){unsigned cost=0;for(unsigned i=0;i<n;++i){auto a=(at+i)&0xffffff;if(a<0x400000||(a>=0xfffd10&&a<0xffffa0)){if((last&1)||a!=unsigned(last|1))cost+=a<0x400000?3:1;last=int(a);}else{cost+=a>=0xffffa0?1:3;last=-1;}}return cost;}
 static FlashCredits credits(const T&t,const Stage1Cpu&c,unsigned len){FlashCredits cr;auto last=int(c.getPC()+len-1);cr.pushLong=8+bus(c.getSP()-4,4,c.writeHistory());cr.popLong=8+bus(c.getSP(),4,last);cr.pushWord=5+bus(c.getSP()-2,2,c.writeHistory());cr.popWord=5+bus(c.getSP(),2,last);cr.call=8+bus(c.getSP()-4,4,c.writeHistory());cr.shortCall=3+bus(c.getSP()-4,4,c.writeHistory());cr.ret=5+bus(c.getSP(),4,last);if(t.stage()==S::Read)cr.read=bus(t.source()+t.index(),1,last);if(t.stage()==S::PublishFirst||t.stage()==S::PublishStrobe||t.stage()==S::PublishData||t.stage()==S::PublishRelease)cr.write=1;return cr;}
 static void project(const T&t,Stage1Cpu&c){auto kind=t.kind();auto at=unsigned(c.getPC())-1;switch(t.stage()){
 case S::Retain:push(c,kind==K::String?5:kind==K::RawData?0:6,kind!=K::String);break;case S::Bind:c.reg32(5)=c.reg32(6);val(c,c.reg32(5));break;case S::DispatchCharacter:midi_projection::call(c,0x237e,0x23aa,false);break;case S::Restore:pop(c,kind==K::String?5:0,kind!=K::String);break;case S::Return:midi_projection::ret(c);break;
 case S::PrepareFirst:case S::PrepareRelease:c.reg8(8)=0x48;val(c,c.reg8(8));break;case S::PrepareStrobe:c.reg8(8)=int8_t(0xc8);val(c,c.reg8(8));break;
 case S::Ready:midi_projection::call(c,0x22fc,kind==K::Data?0x231c:0x2376,kind==K::DirectData);break;case S::CompareAddress:(void)midi_projection::arithmetic(c,uint8_t(c.reg8(14)),8,8,true);break;case S::PrepareWrap:c.reg8(14)=int8_t(0xc0);val(c,c.reg8(14));break;case S::Wrap:midi_projection::call(c,0x2284,0x2326,true);break;case S::ReadyAgain:midi_projection::call(c,0x22fc,0x2328,false);break;case S::RestoreData:pop(c,6,true);break;case S::DispatchData:midi_projection::call(c,kind==K::Character?0x2318:0x22c0,kind==K::Data?0x232c:kind==K::DirectData?0x237c:0x2386,kind!=K::Data);break;
 case S::PrepareCommand1:c.reg8(14)=0x38;val(c,c.reg8(14));break;case S::PrepareCommand2:c.reg8(14)=0x0c;val(c,c.reg8(14));break;case S::PrepareCommand3:c.reg8(14)=1;val(c,c.reg8(14));break;case S::Command1:case S::Command2:case S::Command3:midi_projection::call(c,0x2306,at+2,false);break;
 case S::CursorValue:c.reg8(14)=int8_t(midi_projection::arithmetic(c,uint8_t(c.reg8(14)),kind==K::Cursor?0x80:0x40,8,false));break;case S::CursorCommand:midi_projection::call(c,0x2306,kind==K::Cursor?0x2340:0x236e,kind==K::Cgram);break;
 case S::PrepareSpace:c.reg8(14)=0x20;val(c,0x20);break;case S::WriteSpace:midi_projection::call(c,0x2318,0x2346,false);break;case S::DecrementSpaces:{int old=c.reg8(6),value=old-1;val(c,value);if((old&~value)&128)c.ccr|=2;c.reg8(6)=int8_t(value);break;}
 case S::PrepareLine:case S::PrepareLineAgain:c.reg8(14)=kind==K::FirstLine?0:0x40;val(c,c.reg8(14));break;case S::LineCursor:case S::LineCursorAgain:midi_projection::call(c,0x233c,at+2,false);break;case S::CountLine:c.reg8(6)=8;val(c,8);break;case S::LineSpaces:midi_projection::call(c,0x2342,at+2,false);break;
 case S::TestSign:val(c,c.reg8(14));break;case S::CompareClear:(void)midi_projection::arithmetic(c,uint8_t(c.reg8(14)),255,8,true);break;case S::ClearSecond:midi_projection::call(c,0x235a,0x238e,false);break;case S::ClearFirst:midi_projection::call(c,0x234c,0x2390,false);break;case S::CompareControl:(void)midi_projection::arithmetic(c,uint8_t(c.reg8(14)),0x88,8,true);break;case S::AdjustControl:c.reg8(14)=int8_t(midi_projection::arithmetic(c,uint8_t(c.reg8(14)),0x38,8,false));break;case S::ControlCommand:midi_projection::call(c,0x2306,0x239c,true);break;
 default:break;}}
 std::array<T,16>jobs_{};unsigned depth_=0;uint64_t steps_=0;NativeFlashState lcd_;
};
